/** 供不同环境，注入不同变量初始化 */
export const setup = () => {
  app.registerExtension({
    name: "waitBatchToolsApp",
    async init() {
      try {
        await injectEntry();
      } catch (e) {
        console.error("Failed to get comfyui web application because of ", e);
      }
    },
  });
};

